COMMENT ON TABLE "Usuario" IS 'Usuario principal del sistema. Estatus se representa como smallint para PostgreSQL y corresponde conceptualmente a byte en C#.';

COMMENT ON TABLE "SexoBiologico" IS 'Sexo biológico utilizado por los métodos de estimación energética. No representa identidad de género.';

COMMENT ON TABLE "NivelActividadFisica" IS 'Catálogo de niveles de actividad utilizados por los cálculos energéticos.';

COMMENT ON TABLE "PerfilUsuario" IS 'Perfil antropométrico y energético actual del usuario.';

COMMENT ON TABLE "EstadoFisiologico" IS 'Catálogo de estados fisiológicos relevantes para el contexto nutricional.';

COMMENT ON TABLE "HistorialEstadoFisiologico" IS 'Historial temporal del estado fisiológico del usuario.';

COMMENT ON TABLE "TipoMedicionCorporal" IS 'Define qué medición corporal se registra, por ejemplo peso, cintura, grasa corporal o masa muscular.';

COMMENT ON TABLE "MedicionCorporal" IS 'Registro histórico de mediciones corporales.';

COMMENT ON TABLE "TipoObjetivo" IS 'Catálogo de objetivos como pérdida de peso, mantenimiento o ganancia.';

COMMENT ON TABLE "ObjetivoNutricional" IS 'Objetivo nutricional definido por el usuario. El ritmo objetivo es calculado por la lógica de dominio.';

COMMENT ON TABLE "MetodoCalculoEnergetico" IS 'Método utilizado para estimar gasto energético. Permite evolucionar las fórmulas sin modificar la estructura principal.';

COMMENT ON TABLE "EstimacionEnergetica" IS 'Resultado de un cálculo energético junto con los datos usados para reproducirlo.';

COMMENT ON TABLE "TipoFuenteMetaCalorica" IS 'Origen de una meta calórica: calculada, proporcionada por nutricionista, introducida por usuario, etc.';

COMMENT ON TABLE "MetaCalorica" IS 'Meta calórica vigente para el usuario. Puede provenir de una estimación, un profesional o una captura manual.';

COMMENT ON TABLE "NivelRiesgo" IS 'Nivel lógico de riesgo. La interfaz puede mapear el código a colores sin almacenar colores en la base.';

COMMENT ON TABLE "ReglaRiesgoObjetivo" IS 'Regla configurable utilizada para evaluar el ritmo del objetivo.';

COMMENT ON TABLE "EvaluacionObjetivo" IS 'Resultado determinista de la evaluación del objetivo.';

COMMENT ON TABLE "ReglaRiesgoMetaCalorica" IS 'Reglas configurables para evaluar metas calóricas.';

COMMENT ON TABLE "EvaluacionMetaCalorica" IS 'Evaluación determinista de una meta calórica.';

COMMENT ON TABLE "MetaNutriente" IS 'Meta específica para un nutriente.';

COMMENT ON TABLE "FuenteAlimento" IS 'Fuente del dato alimenticio, por ejemplo USDA, fabricante, catálogo propio o usuario.';

COMMENT ON TABLE "CategoriaAlimento" IS 'Categoría jerárquica de alimentos.';

COMMENT ON TABLE "CocinaAlimentaria" IS 'Clasificación cultural o culinaria del alimento.';

COMMENT ON TABLE "Marca" IS 'Marca comercial asociada a un alimento.';

COMMENT ON TABLE "EstadoPreparacionAlimento" IS 'Estado del alimento, por ejemplo crudo, cocido, congelado o deshidratado.';

COMMENT ON TABLE "MetodoPreparacion" IS 'Método culinario, por ejemplo hervido, frito, asado, horneado o salteado.';

COMMENT ON TABLE "Alimento" IS 'Concepto canónico del alimento. No almacena directamente la fuente nutricional.';

COMMENT ON TABLE "AlimentoFuente" IS 'Representación de un alimento proveniente de una fuente concreta. Permite versionado y trazabilidad.';

COMMENT ON TABLE "AlimentoNutriente" IS 'Cantidad del nutriente asociada a una fuente específica de alimento.';

COMMENT ON TABLE "BaseNutricionalAlimento" IS 'Base sobre la que se expresa la información nutricional: 100 g, 100 ml, una pieza, 30 g, etc.';

COMMENT ON TABLE "ConversionUnidad" IS 'Conversión entre unidades de medida compatibles.';

COMMENT ON TABLE "PorcionAlimento" IS 'Porciones prácticas del alimento, por ejemplo 1 tortilla, 1 taza, 1 cucharada o 1 pieza.';

COMMENT ON TABLE "RecetaAlimento" IS 'Define un alimento como receta y permite registrar rendimiento, merma y cantidad de porciones.';

COMMENT ON TABLE "IngredienteReceta" IS 'Ingrediente de una receta. Debe existir exactamente uno entre IdAlimento e IdRecetaComponente. Permite recetas anidadas: tacos, salsas, guacamole, aderezos, etc.';

COMMENT ON TABLE "RecetaUsuario" IS 'Receta creada o personalizada por un usuario.';

COMMENT ON TABLE "ProfesionalNutricion" IS 'Información del profesional que proporciona un plan alimenticio.';

COMMENT ON TABLE "PlanAlimenticio" IS 'Plan alimenticio estructurado. Puede provenir de un profesional, usuario o importación asistida por IA.';

COMMENT ON TABLE "RegistroComida" IS 'Consumo real registrado por el usuario. Es independiente del plan alimenticio.';

COMMENT ON TABLE "AlimentoRegistroComida" IS 'Alimento identificado dentro de una comida real, incluyendo cantidad y estimación energética.';

COMMENT ON TABLE "BalanceCalorico" IS 'Balance energético diario calculado a partir del consumo registrado y la meta aplicable.';

COMMENT ON TABLE "Imagen" IS 'Metadatos de una imagen. El archivo físico puede almacenarse fuera de PostgreSQL.';

COMMENT ON TABLE "ProveedorIA" IS 'Proveedor abstracto de modelos de IA. La aplicación no depende directamente de Ollama.';

COMMENT ON TABLE "ModeloIA" IS 'Modelo concreto utilizado para inferencia.';

COMMENT ON TABLE "AnalisisImagen" IS 'Ejecución de análisis de una imagen mediante un modelo de IA. ResultadoJson es trazabilidad, no la fuente de verdad del dominio.';

COMMENT ON TABLE "PrediccionAlimento" IS 'Predicción generada por IA antes o durante su validación por el usuario.';

COMMENT ON TABLE "AlimentoEmbedding" IS 'Embedding asociado al alimento para búsqueda semántica o recuperación. La dimensión se configura según el modelo utilizado.';

COMMENT ON TABLE "EvaluacionAnalisisIA" IS 'Feedback utilizado como dato de evaluación. No implica entrenamiento automático del modelo.';

COMMENT ON TABLE "CorreccionPrediccion" IS 'Corrección explícita de una predicción. Se conserva como evidencia de evaluación y no como entrenamiento automático.';

COMMENT ON TABLE "Conversacion" IS 'Conversación independiente de la interfaz. Chat, orb u otra interfaz utilizan el mismo caso de uso.';

COMMENT ON TABLE "Mensaje" IS 'Mensaje individual de una conversación.';

COMMENT ON TABLE "EvaluacionMensaje" IS 'Feedback sobre la calidad de una respuesta conversacional.';

COMMENT ON TABLE "ImportacionPlan" IS 'Conserva la entrada original y la interpretación realizada para convertir texto o imágenes en un plan estructurado.';

